{
  "name": "loss_pairwise_advantage_tanh_relu",
  "intuition": "Use a smooth nonlinear advantage-based transformation combining tanh and relu to model preference strength, enabling soft margin and zeroing negative contributions, with mean aggregation.",
  "pseudocode": "adv = advantage_w - advantage_l\ntransformed = relu(tanh(scale * adv))\nloss = weight * (1 - transformed)\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_advantage_transform",
    "signal_family": "advantage_gap",
    "link_family": "tanh_relu",
    "agg_family": "mean",
    "constraint_family": "relu_zeroing"
  },
  "operators_used": ["tanh", "relu", "mul", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    adv_gap = adv_w - adv_l\n    transformed = ops.relu(ops.tanh(ops.mul(scale, adv_gap)))\n    loss = ops.mul(weight, ops.sub(ops.ones_like(transformed), transformed))\n    return ops.mean(loss)"
}

{
  "name": "pairwise_preference_loss",
  "intuition": "This loss computes a preference score based on the difference in log_probs scaled by their associated quality signals such as cost gap or advantage. By encouraging the model to assign higher probabilities to better options, it directly optimizes for the preference indicated by the signals, leading to better ranking and decision quality.",
  "pseudocode": "preference_score = log_sigmoid(weight * (log_prob_w - log_prob_l) + alpha * signal); loss = -preference_score; return mean(loss)",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "scalar",
    "link_family": "logistic",
    "agg_family": "pairwise",
    "constraint_family": "preference"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    cost_gap = batch.get(\"cost_gap\", ops.zeros_like(log_prob_w))\n    # Compute preference score using logistic link\n    signal = cost_gap\n    # Preference based on scaled difference in log probs\n    diff = log_prob_w - log_prob_l\n    preference = ops.logsigmoid(ops.mul(weight, diff) + ops.mul(alpha, signal))\n    loss = -preference\n    return ops.mean(loss)"
}

{
  "name": "loss_rank_gap_tanh_advantage",
  "intuition": "Use a rank-based paradigm shifting from margin losses to directly optimize a differentiable approximation of rank gap weighted by advantage differences, employing a tanh link to symmetrically penalize incorrect orderings.",
  "pseudocode": "rank_gap = (rank of log_prob_w) - (rank of log_prob_l)\nadv_gap = advantage_w - advantage_l\nscaled_gap = tanh(scale * rank_gap * adv_gap)\nloss = mean(weight * relu(-scaled_gap))",
  "hyperparams": {
    "paradigm_family": "rank_approximation",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "relu_clipping"
  },
  "operators_used": ["tanh", "relu", "mul", "sub", "mean", "rank_gap"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    alpha = float(extra.get('alpha', 1.0))\n    # compute rank gap between winning and losing log probs\n    rg = ops.rank_gap(lpw, lpl)  # positive if w ranks higher\n    adv_gap = adv_w - adv_l\n    scaled = ops.tanh(alpha * rg * adv_gap)\n    # penalize negative scaled values (wrong orderings weighted by advantage)\n    loss_per_pair = ops.relu(-scaled)\n    if weight is not None:\n        loss_per_pair = loss_per_pair * weight\n    return ops.mean(loss_per_pair)"
}

{
  "name": "loss_advantage_tanh_rank_gap",
  "intuition": "Use a pairwise rank-based loss that incorporates advantage signals with a smooth tanh link to encourage margin-sensitive ordering, aggregating by median for robustness and applying a positivity constraint for stable gradients.",
  "pseudocode": "rank_gap = delta_rank\\nadvantage_diff = advantage_w - advantage_l\\nx = tanh(alpha * rank_gap * advantage_diff)\\nloss = relu( - x )\\nreturn median(loss * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "median",
    "constraint_family": "relu_positivity"
  },
  "operators_used": ["tanh", "relu", "median", "sub", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "delta_rank"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    delta_rank = batch['delta_rank']\n    alpha = float(extra.get('alpha', 1.0))\n    adv_diff = ops.sub(adv_w, adv_l)\n    x = ops.tanh(ops.mul(ops.mul(alpha, delta_rank), adv_diff))\n    loss = ops.relu(ops.neg(x))\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.median(loss)"
}

{
  "name": "pairwise_preference_signal_loss",
  "intuition": "This loss leverages pairwise differences in quality signals (e.g., cost_gap) between preferred and non-preferred options, encouraging the model to assign higher probabilities to better options. Using pairwise signals helps the model learn relative preferences, which is effective in ranking tasks and preference learning in RL4CO.",
  "pseudocode": "scalar = sum_over_pairs(logsigmoid(log_prob_w - log_prob_l + alpha * (cost_gap)))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "pairwise_signals",
    "link_family": "logistic",
    "agg_family": "pairwise_aggregation",
    "constraint_family": "relative_comparison",
    "other_hparams": "alpha=1.0"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    cost_gap = batch.get(\"cost_gap\", ops.zeros_like(log_prob_w))\n    # Compute pairwise preference signal\n    diff = log_prob_w - log_prob_l + alpha * cost_gap\n    # Apply logsigmoid to get preference likelihood\n    preference_scores = ops.logsigmoid(diff)\n    # Compute mean over pairs\n    loss = -ops.mean(preference_scores * batch[\"weight\"])\n    return loss"
}

{
  "name": "pairwise_pref_loss",
  "intuition": "This loss encourages the model to prefer higher-quality outputs by comparing pairwise scores based on their cost gap and advantage signals. Using the difference in log probabilities weighted by advantage differences emphasizes the preferred candidate, aligning the model's preferences with quality signals. This penalizes pairs where the lower-quality candidate is ranked higher, promoting consistent preference calibration.",
  "pseudocode": "loss = mean( logsigmoid( (log_prob_w - log_prob_l) * advantage_diff ) ) where advantage_diff = advantage_w - advantage_l",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "preference_signals",
    "link_family": "logistic",
    "agg_family": "mean",
    "constraint_family": "pairwise_dominance",
    "other_hparams": "{}"
  },
  "operators_used": ["logsigmoid", "sub", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    advantage_w = batch.get('advantage_w', ops.zeros_like(log_prob_w))\n    advantage_l = batch.get('advantage_l', ops.zeros_like(log_prob_l))\n    weight = batch['weight']\n    advantage_diff = ops.sub(advantage_w, advantage_l)\n    score_diff = ops.sub(log_prob_w, log_prob_l)\n    scaled_diff = ops.mul(score_diff, advantage_diff)\n    loss = ops.mean(ops.logsigmoid(scaled_diff))\n    return loss"
}

