{
  "name": "loss_rank_gap_tanh_cost_gap_repaired_v4",
  "intuition": "Same rank-based loss using clamped cost gap with stable gradients and safe weighted mean for joint gate pass",
  "pseudocode": "rank_gap = ops.rank_gap(log_prob_w, log_prob_l)\ncost_gap = (cost_b - cost_a).clamp(min=-10, max=10)\nscaled = tanh(alpha * rank_gap * cost_gap)\nloss = weighted_mean(weight * relu(-scaled))",
  "hyperparams": {
    "paradigm_family": "rank_approximation",
    "signal_family": "cost_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "relu_clipping"
  },
  "operators_used": ["tanh", "relu", "mul", "sub", "mean", "rank_gap", "clamp", "sum"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch[\"log_prob_w\"]\n    lpl = batch[\"log_prob_l\"]\n    weight = batch.get(\"weight\", lpw.new_ones(lpw.shape))\n    cost_a = batch[\"cost_a\"]\n    cost_b = batch[\"cost_b\"]\n    alpha = float(extra.get(\"alpha\", 1.0))\n    rg = ops.rank_gap(lpw, lpl)\n    cost_gap = (cost_b - cost_a).clamp(min=-10, max=10)\n    scaled = ops.tanh(alpha * rg * cost_gap)\n    loss_per_pair = ops.relu(ops.neg(scaled))\n    loss_weighted = loss_per_pair * weight\n    norm = ops.sum(weight) + eps\n    return ops.sum(loss_weighted) / norm\n"
}

