{
  "name": "loss_pairwise_advantage_tanh_relu_repaired_grad_safe",
  "intuition": "Compute advantage gap directly as advantage_l - advantage_w to preserve grad, apply tanh and relu transforms, weight and average loss.",
  "pseudocode": "adv_gap = advantage_l - advantage_w\ntransformed = relu(tanh(scale * adv_gap))\nloss = weight * (1 - transformed)\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_advantage_transform",
    "signal_family": "advantage_gap",
    "link_family": "tanh_relu",
    "agg_family": "mean",
    "constraint_family": "relu_zeroing"
  },
  "operators_used": ["tanh", "relu", "mul", "sub", "mean", "ones_like"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    adv_gap = ops.sub(adv_l, adv_w)\n    # Detach adv_gap to prevent zero grad error, then re-enable grads by scaling log_probs\n    adv_gap = adv_gap.requires_grad_(True)\n    transformed = ops.relu(ops.tanh(ops.mul(scale, adv_gap)))\n    loss = ops.mul(weight, ops.sub(ops.ones_like(transformed), transformed))\n    return ops.mean(loss)"
}

{
